// Element data and electron configurations.
//
// The data comes from data/elements.json, generated by
// tools/build_elements.py from cited sources (PubChem periodic table;
// Clementi & Raimondi 1963 / Clementi, Raimondi & Reinhardt 1967 effective
// nuclear charges). Orbitals are hydrogen-like with these Z_eff, in a fixed
// orientation in the atom frame. Within a p, d or f subshell orbitals fill
// by Hund's rule in a fixed order (p: x, y, z; d: xy, yz, xz, x²−y², z²;
// f: z³, xz², yz², xyz, z(x²−y²), x(x²−3y²), y(3x²−y²)): singly, then paired.
//
// Elements whose ground state needs a Z_eff the tables don't have are kept
// (so Z indexes stay simple) but marked `supported: false`; the UI greys
// them out.

import { ORBITALS, SUBSHELLS, AUFBAU, orbitalsOf } from './orbitals.js';

export { ORBITALS } from './orbitals.js';

// Highest Z enabled in the app (the JSON may contain more).
export const MAX_Z = 54;

const CAPACITY = { 0: 2, 1: 6, 2: 10, 3: 14 };
const SUP = '⁰¹²³⁴⁵⁶⁷⁸⁹';
const sup = n => String(n).split('').map(c => SUP[+c]).join('');

// Ground-state subshell occupancy by the Aufbau order (used by tests; real
// configurations, including exceptions, come from the data).
export function aufbau(z) {
  const out = {};
  let left = z;
  for (const id of AUFBAU) {
    if (left <= 0) break;
    const cap = CAPACITY[SUBSHELLS.find(s => s.id === id).l];
    out[id] = Math.min(cap, left);
    left -= out[id];
  }
  return out;
}

// Distribute `count` electrons over the orbitals of a subshell (Hund).
export function hundFill(count, nOrbitals) {
  const occ = new Array(nOrbitals).fill(0);
  for (let e = 0; e < count; e++) occ[e % nOrbitals]++;
  return occ;
}

export function orbitalOccupancy(subshellOcc) {
  const occ = new Array(ORBITALS.length).fill(0);
  for (const [id, count] of Object.entries(subshellOcc)) {
    const idx = orbitalsOf(id);
    hundFill(count, idx.length).forEach((c, j) => { occ[idx[j]] = c; });
  }
  return occ;
}

export function electronConfig(subshellOcc) {
  return SUBSHELLS.filter(s => subshellOcc[s.id])
    .map(s => s.id + sup(subshellOcc[s.id])).join(' ');
}

// Noble-gas cores for shorthand configurations (largest first).
const AR = { '1s': 2, '2s': 2, '2p': 6, '3s': 2, '3p': 6 };
const KR = { ...AR, '3d': 10, '4s': 2, '4p': 6 };
const XE = { ...KR, '4d': 10, '5s': 2, '5p': 6 };
const NOBLE_CORES = [
  ['Xe', 54, XE],
  ['Kr', 36, KR],
  ['Ar', 18, AR],
  ['Ne', 10, { '1s': 2, '2s': 2, '2p': 6 }],
  ['He', 2, { '1s': 2 }],
];

// "[Ne] 3s² 3p⁴" for Z > 10; the full configuration for periods 1-2,
// which are short enough to read in full.
export function shortConfig(z, subshellOcc) {
  if (z <= 10) return electronConfig(subshellOcc);
  for (const [sym, zc, core] of NOBLE_CORES) {
    if (z <= zc) continue;
    if (!Object.entries(core).every(([id, c]) => subshellOcc[id] === c)) continue;
    const rest = Object.fromEntries(Object.entries(subshellOcc).filter(([id]) => !(id in core)));
    return `[${sym}] ` + electronConfig(rest);
  }
  return electronConfig(subshellOcc);
}

export function periodOf(z) {
  return z <= 2 ? 1 : z <= 10 ? 2 : z <= 18 ? 3 : z <= 36 ? 4 : z <= 54 ? 5 : 6;
}

function fromJson(d) {
  return {
    z: d.z, symbol: d.symbol, name: d.name, mass: d.mass, group: d.group,
    category: d.category,
    period: d.period,
    electronegativity: d.electronegativity,
    ionizationEnergy: d.ionizationEnergy,
    supported: d.supported !== false,
    unsupportedReason: d.unsupportedReason || null,
    subshells: d.subshells,                                   // { '1s': 2, ... }
    occupancy: orbitalOccupancy(d.subshells),                 // per ORBITALS index
    zeff: ORBITALS.map(o => d.zeff[o.subshell] ?? 0),         // per ORBITALS index
    zeffBySubshell: d.zeff,
    config: electronConfig(d.subshells),
    configShort: shortConfig(d.z, d.subshells),
  };
}

async function loadElements() {
  const res = await fetch(new URL('../data/elements.json', import.meta.url));
  if (!res.ok) throw new Error(`Could not load data/elements.json (${res.status})`);
  const doc = await res.json();
  return doc.elements.filter(d => d.z <= MAX_Z).map(fromJson);
}

export const ELEMENTS = await loadElements();

export function elementByZ(z) {
  return ELEMENTS[z - 1];
}

// Next selectable (supported) element from z in direction dir (+1 / -1),
// or null at the ends.
export function stepElement(z, dir) {
  for (let k = z + dir; k >= 1 && k <= ELEMENTS.length; k += dir) {
    if (ELEMENTS[k - 1].supported) return k;
  }
  return null;
}
